      const kk = 1 + 0.09 * Math.sin(d.x * 3.1 + sd) * Math.sin(d.y * 2.7 + sd * 1.7) * Math.sin(d.z * 2.9 + sd * 0.6) + 0.04 * Math.sin(d.x * 7 + sd) * Math.sin(d.y * 8 + d.z * 6 + sd);
